from httpbin.core import app
client = app.test_client()

def test_weighted_comma_codes_returns_one_of_specified():
    valid = {200, 201}
    for _ in range(10):
        r = client.get('/status/200,201')
        assert r.status_code in valid, f"Got unexpected {r.status_code}"

test_weighted_comma_codes_returns_one_of_specified()
